import {prepararActualizacion} from '/comunidad/actualizacion.mjs';
prepararActualizacion();
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconos={buscar:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',explorar:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>',citas:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M3 10h18M8 3v4m8-4v4"/>',favoritos:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 8 15 8 15S25 10 20 5Z"/>',perfil:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',foto:'<rect x="3" y="4" width="18" height="17" rx="3"/><circle cx="8" cy="9" r="1.5"/><path d="m3 18 5-5 4 3 4-6 5 7"/>',guardar:'<path d="M6 3h12v19l-6-4-6 4Z"/>',compartir:'<path d="M12 16V2m-5 5 5-5 5 5M5 11v10h14V11"/>',comentarios:'<path d="M21 11a9 9 0 0 1-9 9H3l2-4a9 9 0 1 1 16-5Z"/>',microfono:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M6 10a6 6 0 0 0 12 0m-6 6v6m-4 0h8"/>'};
const svg=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${iconos[n]||iconos.foto}</svg>`,money=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(n),norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const categorias=['Cejas','Pestañas','Uñas','Depilación','Cabello','Maquillaje','Facial','Barbería'];
let tab='explorar',vista='directorio',q='',ciudad='',pos=null,orden='recomendados',hoy=false,noche=false,perfiles=[],trabajos=[],cliente=null,perfil=null,perfilTab='Precios',version=0,avisador,config,widget=null,tokenCaptcha='',revisionHoja=0;
try{document.documentElement.dataset.theme=localStorage.getItem('agendappx.cliente.apariencia')||'light';ciudad=localStorage.getItem('agendappx.cliente.ciudad')||'';}catch{}
async function api(path,d,privada=false){const s=privada?await window.AgendappxCuentas.sesionCliente():null;if(privada&&!s)throw new Error('Entra con WhatsApp para continuar.');const r=await fetch(path,{method:d===undefined?'GET':'POST',headers:{...(d!==undefined?{'Content-Type':'application/json'}:{}),...(s?{Authorization:'Bearer '+s.accessToken}:{})},...(d===undefined?{}:{body:JSON.stringify(d)}),cache:'no-store',signal:AbortSignal.timeout(18000)});const b=await r.json();if(!r.ok)throw new Error(b.error||'No se pudo cargar. Intenta de nuevo.');return b;}
const aviso=t=>{clearTimeout(avisador);$('#aviso').textContent=t;$('#aviso').hidden=false;avisador=setTimeout(()=>$('#aviso').hidden=true,5000);};
function hoja(t,html){revisionHoja++;tokenCaptcha='';if(widget!==null){try{window.turnstile?.remove(widget);}catch{}widget=null;}$('#titulo-hoja').textContent=t;$('#cuerpo-hoja').innerHTML=html;if(!$('#hoja').open)$('#hoja').showModal();$('#cuerpo-hoja').scrollTop=0;document.dispatchEvent(new Event('agendappx:hoja'));return revisionHoja;}
function cerrar(){$('#hoja').close();revisionHoja++;if(widget!==null){try{window.turnstile?.remove(widget);}catch{}widget=null;}tokenCaptcha='';}
$('#cerrar').onclick=cerrar;$('#listo').onclick=()=>{cerrar();void actualizarCliente().then(()=>render());};
async function captcha(accion){const rev=revisionHoja;config??=await api('/api/cuentas/config');if(!config.registro?.turnstileSiteKey)throw new Error('La verificación está pendiente de configurar.');if(!window.turnstile)await new Promise((ok,no)=>{let s=document.querySelector('script[data-captcha-social]');const t=setTimeout(()=>no(new Error('Revisa tu conexión para verificar la seguridad.')),10000);const listo=()=>{clearTimeout(t);ok();};if(s){s.addEventListener('load',listo,{once:true});return;}s=document.createElement('script');s.dataset.captchaSocial='si';s.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';s.async=true;s.onload=listo;s.onerror=()=>{clearTimeout(t);no(new Error('No se pudo cargar la verificación.'));};document.head.append(s);});if(rev!==revisionHoja||!$('#captcha-social'))return;widget=window.turnstile.render($('#captcha-social'),{sitekey:config.registro.turnstileSiteKey,action:accion,size:'flexible',callback:t=>tokenCaptcha=t,'expired-callback':()=>tokenCaptcha='','error-callback':()=>tokenCaptcha=''});}
async function actualizarCliente(){try{cliente=await window.AgendappxCuentas.sesionCliente();}catch{cliente=null;}}
function nav(){$('#pestanas').innerHTML=[['explorar','Explorar'],['citas','Mis citas'],['favoritos','Favoritos'],['perfil','Perfil']].map(([id,t])=>`<button type="button" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${svg(id)}<span>${t}</span></button>`).join('');$('#buscar-circulo').innerHTML=svg('buscar');$('#ubicacion').textContent=pos?'Cerca de ti⌄':ciudad?ciudad+'⌄':'Elegir ubicación⌄';}
const vacio=t=>`<p class="vacio">${esc(t)}</p>`;
function buscador(){return `<form class="buscador" id="buscar-form" role="search">${svg('buscar')}<input id="buscar" type="search" aria-label="Buscar servicios o negocios" placeholder="Cejas, pestañas, uñas…" autocomplete="off" value="${esc(q)}"><button type="button" id="microfono" aria-label="Buscar con voz">${svg('microfono')}</button></form>`;}
function foto(f,alt,clase=''){return f?`<img class="${clase}" src="${esc(f)}" alt="${esc(alt)}" loading="lazy" decoding="async">`:`<div class="sin-foto ${clase}" aria-label="Sin foto">${svg('foto')}</div>`;}
function calificacion(p){return p.resenas?`<span class="estrellas">★</span> ${Number(p.promedio).toFixed(1)} <span class="muted">(${p.resenas} reseñas)</span>`:'<span class="muted">Sin reseñas</span>';}
function favorito(tipo,id){return !!cliente?.guardados?.some(g=>g.tipo===tipo&&g.destino===id);}
function local(p){const fotos=[p.portada,...p.servicios.map(s=>s.foto)].filter(Boolean).slice(0,3),coincidencias=p.coincidencias?.length?p.coincidencias:p.servicios;return `<article class="local"><button type="button" data-perfil="${esc(p.slug)}" style="padding:0;width:100%;text-align:left"><div class="local-fotos">${fotos.length?fotos.map(f=>foto(f,p.nombre)).join(''):foto(null,'')}</div><div class="local-cuerpo"><h3>${esc(p.nombre)}${p.verificado?' ✓':''}</h3><p class="sub">${calificacion(p)}${p.km===null?'':' · '+p.km.toFixed(1)+' km'}</p><p class="sub">${esc(p.colonia||p.ciudad)} · ${abierto(p)?'Abierto':'Cerrado'} · cierra ${esc(p.cierra)}</p>${coincidencias.slice(0,2).map(s=>`<div class="servicio-resumen"><span>${esc(s.nombre)} · ${s.duracion} min</span><b>${money(s.precio)}</b></div>`).join('')}</div></button><div class="local-cuerpo local-acciones"><span class="proximo">${p.proximo?'Próximo: '+esc(p.proximo.fecha.slice(5))+' '+esc(p.proximo.hora):'Sin horarios publicados'}</span><button type="button" class="capsula" data-perfil="${esc(p.slug)}">Ver horarios</button></div></article>`;}
function abierto(p){const t=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Mexico_City',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());return t>=p.abre&&t<p.cierra;}
function paginaExplorar(){const fotos=categorias.map(c=>perfiles.flatMap(p=>p.servicios).find(s=>norm(s.categoria)===norm(c)&&s.foto)?.foto);return `<h1>¿Qué te quieres<br>hacer hoy?</h1>${buscador()}<div class="segmentado"><button type="button" data-vista="directorio" aria-selected="${vista==='directorio'}">Explorar</button><button type="button" data-vista="social" aria-selected="${vista==='social'}">Social</button></div>${!q&&vista==='directorio'?`<div class="categorias">${categorias.map((c,i)=>`<button type="button" class="categoria" data-categoria="${esc(c)}">${foto(fotos[i],c)}<span>${esc(c)}</span></button>`).join('')}</div>`:''}<div class="filtros"><select id="orden" aria-label="Ordenar resultados">${[['recomendados','Recomendados'],['calificacion','Calificación'],['cercania','Cercanía'],['precio','Precio']].map(([v,l])=>`<option value="${v}" ${v===orden?'selected':''}>${l}</option>`).join('')}</select><button type="button" data-filtro="hoy" aria-pressed="${hoy}">Con lugar hoy</button><button type="button" data-filtro="noche" aria-pressed="${noche}">Abierto de noche</button></div><div id="resultados">${resultados()}</div><section class="promocion-negocio"><h2>¿Tienes un salón?</h2><p class="sub">Tu agenda, tus trabajos y tus próximas clientas.</p><a class="capsula" href="/#registro">Súmate a Agendappx</a></section>`;}
function resultados(){if(vista==='directorio')return `<div class="encabezado"><h2>${q?'Resultados para «'+esc(q)+'»':'Mejor calificados cerca de ti'}</h2></div><div class="tarjetas">${perfiles.map(local).join('')||vacio('Aún no hay negocios publicados para esta búsqueda.')}</div>`;
 const historias=perfiles.filter(p=>cliente?.siguiendo?.includes(p.id)),porden=new Map(perfiles.map((p,i)=>[p.id,i]));const grupo=t=>cliente?.siguiendo?.includes(t.negocioId)?0:t.meGusta>0&&(perfiles.find(p=>p.id===t.negocioId)?.km??99)<=10?1:2;const feed=[...trabajos].sort((a,b)=>grupo(a)-grupo(b)||b.fecha.localeCompare(a.fecha));return `${historias.length?`<div class="storys">${historias.map(p=>`<button type="button" data-perfil="${esc(p.slug)}">${foto(p.logo||p.portada,p.nombre)}${esc(p.nombre)}</button>`).join('')}</div>`:''}${q?`<div class="encabezado"><h2>Locales que hacen ${esc(q)}</h2></div><div class="tarjetas">${perfiles.map(local).join('')||vacio('Sin locales que coincidan.')}</div>`:''}<div class="encabezado"><h2>${q?'Trabajos':'Para ti'}</h2></div><div class="feed">${feed.map(post).join('')||vacio('Todavía no hay trabajos publicados.')}</div>`;}
function post(t){const siguiendo=cliente?.siguiendo?.includes(t.negocioId),gusta=cliente?.meGusta?.includes(t.id);return `<article class="post"><div class="post-cabecera"><button type="button" data-perfil="${esc(t.slug)}"><b>${esc(t.negocio)}</b><small>${esc(t.categoria)}</small></button><button type="button" class="capsula secundario" data-seguir="${esc(t.negocioId)}">${siguiendo?'Siguiendo':'Seguir'}</button></div><div class="post-foto"><button type="button" data-trabajo="${t.id}">${foto(t.foto,t.servicio)}</button><div class="foto-servicio"><span><b>${esc(t.servicio)}</b><small>${money(t.precio)} · ${t.duracion} min</small></span><button type="button" class="capsula" data-agendar="${esc(t.slug)}" data-servicio="${esc(t.servicioId)}">Agendar</button></div></div><div class="post-acciones"><button type="button" data-gusta="${t.id}" aria-pressed="${!!gusta}">${svg('favoritos')} ${t.meGusta}</button><button type="button" data-trabajo="${t.id}" aria-label="Ver comentarios">${svg('comentarios')} ${t.comentarios}</button><button type="button" data-compartir="${t.id}" aria-label="Compartir trabajo">${svg('compartir')}</button><button type="button" data-guardar="${t.id}" aria-label="Guardar trabajo" aria-pressed="${favorito('trabajo',t.id)}">${svg('guardar')}</button></div><p class="post-texto">${esc(t.texto)}<small class="post-fecha">${new Date(t.fecha).toLocaleDateString('es-MX')}</small></p></article>`;}
async function cargar(){const v=++version;try{const d={q,ciudad,lat:pos?.lat,lon:pos?.lon,orden,hoy,noche};const a=await api('/api/publico/explorar',d);let b;if(vista==='social')b=await api('/api/publico/social',d);if(v!==version)return;perfiles=a.negocios;trabajos=b?.trabajos||trabajos;if(tab==='explorar'&&!perfil){const cont=$('#resultados');if(cont)cont.innerHTML=resultados();else render();}}catch(e){if(v===version){const c=$('#resultados');if(c)c.innerHTML=vacio(e.message);else aviso(e.message);}}}
function render(){nav();if(perfil)return;const m=$('#contenido');if(tab==='explorar'){m.innerHTML=paginaExplorar();}else if(tab==='citas')void misCitas();else if(tab==='favoritos')favoritos();else miPerfil();}
async function entrar(){hoja('Iniciar sesión','<section id="acceso-cliente"></section>');await window.AgendappxCuentas.montar($('#acceso-cliente'),{cliente:true});}
async function requiere(){await actualizarCliente();if(!cliente){await entrar();return false;}return true;}
async function accion(d){if(!await requiere())return false;await api('/api/cliente/accion',d,true);await actualizarCliente();return true;}
async function abrirPerfil(slug,pestana='Precios'){const v=++version;$('#contenido').innerHTML=vacio('Cargando el salón…');try{const p=await api('/api/publico/perfil/'+encodeURIComponent(slug));if(v!==version)return;perfil=p;perfilTab=pestana;history.replaceState(null,'','/'+p.slug);nav();await dibujarPerfil();void api('/api/publico/visita',{negocioId:p.id}).catch(()=>{});}catch(e){perfil=null;$('#contenido').innerHTML=vacio(e.message);}}
async function dibujarPerfil(){const p=perfil;if(!p)return;const imagen=p.portada||p.servicios.find(s=>s.foto)?.foto;$('#contenido').innerHTML=`<button type="button" data-volver>‹ Explorar</button>${imagen?foto(imagen,p.nombre,'portada'):''}<section class="perfil-cabecera"><h1>${esc(p.nombre)}${p.verificado?' ✓':''}</h1><p class="sub">${esc(p.colonia||p.ciudad)}</p><p>${calificacion(p)} · ${p.trabajos} trabajos · ${p.seguidores} seguidores</p><p>${esc(p.descripcion)}</p><div class="perfil-acciones"><button type="button" class="capsula" data-perfil-reservar>Agendar cita</button><button type="button" class="capsula secundario" data-seguir="${p.id}">${cliente?.siguiendo?.includes(p.id)?'Siguiendo':'Seguir'}</button><button type="button" class="capsula secundario favorito" data-favorito="${p.id}" aria-pressed="${favorito('negocio',p.id)}" aria-label="Guardar salón">${svg('favoritos')}</button>${p.whatsapp?`<a class="capsula secundario" target="_blank" rel="noopener noreferrer" href="https://wa.me/${esc(p.whatsapp)}">WhatsApp ↗</a>`:''}${p.direccion||p.colonia?`<a class="capsula secundario" target="_blank" rel="noopener noreferrer" href="https://maps.apple.com/?q=${encodeURIComponent([p.nombre,p.direccion,p.colonia,p.ciudad].filter(Boolean).join(', '))}">Ir ↗</a>`:''}</div></section><div class="perfil-pestanas"><div class="segmentado">${['Precios','Fotos','Horarios','Reseñas'].map(t=>`<button type="button" data-perfil-tab="${t}" aria-selected="${perfilTab===t}">${t}</button>`).join('')}</div></div><section id="perfil-seccion">${vacio('Cargando…')}</section>`;const root=$('#perfil-seccion');
 if(perfilTab==='Precios'){const ordenados=[...p.servicios].sort((a,b)=>Number(norm(b.categoria).includes(norm(q))&&!!q)-Number(norm(a.categoria).includes(norm(q))&&!!q)||a.categoria?.localeCompare(b.categoria,'es'));root.innerHTML=`<p class="sub">Horario del salón: ${esc(p.abre)} – ${esc(p.cierra)}</p><div class="grupo">${ordenados.map(s=>`<button type="button" class="celda" data-agendar="${esc(p.slug)}" data-servicio="${esc(s.id)}">${s.foto?foto(s.foto,s.nombre):''}<span class="l">${esc(s.nombre)}<small>${esc(s.categoria)} · ${s.duracion} min</small></span><b>${money(s.precio)}</b></button>`).join('')||vacio('El salón aún no ha publicado servicios.')}</div>`;}
 else if(perfilTab==='Fotos'){const d=await api('/api/publico/social',{q:'',ciudad:'',negocioId:p.id});if(perfil!==p)return;const ts=d.trabajos.filter(t=>t.negocioId===p.id);for(const t of ts)if(!trabajos.some(x=>x.id===t.id))trabajos.push(t);root.innerHTML=`<div class="cuadricula">${ts.map(t=>`<button type="button" data-trabajo="${t.id}">${foto(t.foto,t.servicio)}</button>`).join('')}</div>${ts.length?'':vacio('Todavía no hay fotos de trabajos publicadas.')}`;}
 else if(perfilTab==='Horarios'){root.innerHTML=`<label class="campo">Servicio<select id="perfil-servicio">${p.servicios.map(s=>`<option value="${esc(s.id)}">${esc(s.nombre)}</option>`).join('')}</select></label><div id="perfil-horas"></div>`;await horasPerfil();}
 else{const d=await api('/api/publico/resenas',{negocioId:p.id});if(perfil!==p)return;root.innerHTML=`<div class="grupo"><div class="resena">${calificacion(p)}${[5,4,3,2,1].map(n=>`<div class="barra">${n} ★<progress max="${Math.max(1,d.resenas.length)}" value="${d.resenas.filter(r=>r.estrellas===n).length}" aria-label="Reseñas de ${n} estrellas"></progress><span>${d.resenas.filter(r=>r.estrellas===n).length}</span></div>`).join('')}</div>${d.resenas.map(r=>`<article class="resena"><b>${esc(r.nombre)}</b><p class="estrellas">${'★'.repeat(r.estrellas)}</p><small>✓ Cita verificada</small><p>${esc(r.texto)}</p>${r.respuesta?`<p>Respuesta del salón: ${esc(r.respuesta)}</p>`:''}<button type="button" data-reportar="${r.id}" data-tipo="resena">Reportar</button></article>`).join('')||vacio('Sé la primera persona en reseñar después de tu cita.')}</div>`;}
}
async function horasPerfil(){const s=$('#perfil-servicio')?.value,p=perfil;if(!s)return;const d=await api('/api/publico/horarios',{negocioId:p.id,servicio:s});if(perfil!==p||!$('#perfil-horas'))return;$('#perfil-horas').innerHTML=`<div class="horas">${d.horarios.slice(0,50).map(h=>`<button type="button" data-agendar="${esc(p.slug)}" data-servicio="${esc(s)}">${esc(h.fecha.slice(5))} · ${esc(h.hora)}<br><small>${esc(h.persona)}</small></button>`).join('')}</div>${d.horarios.length?'':vacio('No hay huecos para este servicio en los próximos siete días.')}`;}
async function reservar(slug,servicio){const p=perfil?.slug===slug?perfil:await api('/api/publico/perfil/'+encodeURIComponent(slug)),s=servicio?p.servicios.find(s=>s.id===servicio):p.servicios[0];if(!s)return aviso('Este servicio ya no está disponible. Revisa los servicios actuales del salón.');const rev=hoja('Pedir cita',`<p><b>${esc(p.nombre)}</b></p><label class="campo">Servicio<select id="reserva-servicio">${p.servicios.map(x=>`<option value="${esc(x.id)}" ${x.id===s.id?'selected':''}>${esc(x.nombre)} · ${money(x.precio)} · ${x.duracion} min</option>`).join('')}</select></label><p class="sub">El salón debe confirmar tu solicitud. Los horarios se comprueban al enviarla.</p><div id="reserva-horarios">${vacio('Consultando horarios…')}</div><form id="reserva-form"><label class="campo">Tu nombre<input id="reserva-nombre" maxlength="100" autocomplete="name" required value="${esc(cliente?.nombre==='Cliente'?'':cliente?.nombre||'')}"></label><label class="campo">WhatsApp +52<input id="reserva-telefono" inputmode="tel" autocomplete="tel-national" placeholder="10 dígitos" required maxlength="24"></label><label class="celda"><span class="l">Recibir avisos de esta cita por WhatsApp</span><button type="button" id="reserva-consentimiento" class="sw" role="switch" aria-label="Recibir avisos por WhatsApp" aria-checked="false"></button></label><label class="casilla"><input type="checkbox" id="reserva-privacidad" required><span>Autorizo compartir mi nombre y número con este salón para gestionar esta cita.</span></label><div id="captcha-social"></div><p class="sub" id="reserva-error" role="status"></p><button type="submit" class="capsula" id="reserva-enviar">Solicitar cita</button></form>`);let elegida=null,horarios=[],fecha='';const solicitudId=crypto.randomUUID();async function horas(){elegida=null;$('#reserva-horarios').innerHTML=vacio('Consultando…');const d=await api('/api/publico/horarios',{negocioId:p.id,servicio:$('#reserva-servicio').value});if(rev!==revisionHoja)return;horarios=d.horarios;fecha=horarios[0]?.fecha||'';dibujarHoras();}function dibujarHoras(){$('#reserva-horarios').innerHTML=`<div class="horas">${[...new Set(horarios.map(h=>h.fecha))].map(f=>`<button type="button" data-reserva-fecha="${f}" aria-pressed="${f===fecha}">${esc(new Date(f+'T12:00:00').toLocaleDateString('es-MX',{weekday:'short',day:'numeric',month:'short'}))}</button>`).join('')}</div><div class="horas">${horarios.filter(h=>h.fecha===fecha).map((h,i)=>`<button type="button" data-reserva-hora="${i}" aria-pressed="${elegida?.hora===h.hora&&elegida?.personaId===h.personaId}">${h.hora}<br><small>${esc(h.persona)}</small></button>`).join('')}</div>${horarios.length?'':vacio('No hay horarios libres. Elige otro servicio.')}`;}
 $('#reserva-servicio').onchange=()=>void horas().catch(e=>aviso(e.message));$('#reserva-consentimiento').onclick=e=>e.currentTarget.setAttribute('aria-checked',String(e.currentTarget.getAttribute('aria-checked')!=='true'));$('#reserva-horarios').onclick=e=>{const f=e.target.closest('[data-reserva-fecha]'),h=e.target.closest('[data-reserva-hora]');if(f){fecha=f.dataset.reservaFecha;elegida=null;}if(h)elegida=horarios.filter(x=>x.fecha===fecha)[+h.dataset.reservaHora];dibujarHoras();};
 $('#reserva-form').onsubmit=async e=>{e.preventDefault();const boton=$('#reserva-enviar');if(boton.disabled)return;boton.disabled=true;try{if(!elegida)throw new Error('Elige día, hora y especialista.');if(!tokenCaptcha)throw new Error('Completa la verificación de seguridad.');await api('/api/publico/reservar',{negocioId:p.id,servicio:$('#reserva-servicio').value,solicitudId,fecha:elegida.fecha,hora:elegida.hora,personaId:elegida.personaId,nombre:$('#reserva-nombre').value.trim(),telefono:$('#reserva-telefono').value,consentimiento:$('#reserva-consentimiento').getAttribute('aria-checked')==='true',privacidad:$('#reserva-privacidad').checked,origen:vista==='social'?'social':'explorar',captchaToken:tokenCaptcha});hoja('Solicitud recibida',`<h2>Tu solicitud ya está en la agenda</h2><p>${esc(p.nombre)} revisará ${esc(elegida.fecha)} a las ${esc(elegida.hora)}.</p><p class="sub">La cita aún necesita confirmación del salón. Puedes consultar tus citas entrando con tu mismo WhatsApp.</p><button type="button" class="capsula" id="reserva-terminar">Listo</button>`);$('#reserva-terminar').onclick=cerrar;}catch(e){if($('#reserva-error'))$('#reserva-error').textContent=e.message;tokenCaptcha='';if(widget!==null)window.turnstile?.reset(widget);}finally{boton.disabled=false;}};await horas();await captcha('reserva');}
async function verTrabajo(id){const t=trabajos.find(t=>t.id===id);if(!t)return;const d=await api('/api/publico/trabajo',{trabajoId:id});hoja(t.negocio,`${foto(t.foto,t.servicio,'imagen-grande')}<h3>${esc(t.servicio)} · ${money(t.precio)}</h3><p>${esc(t.texto)}</p><button type="button" class="capsula" data-agendar="${esc(t.slug)}" data-servicio="${esc(t.servicioId)}">Agendar · ${t.duracion} min</button><button type="button" data-reportar="${id}" data-tipo="trabajo">Reportar foto</button><h3>Comentarios</h3><div class="grupo">${d.comentarios.map(c=>`<article class="resena"><b>${esc(c.nombre)}</b><p>${esc(c.texto)}</p><button type="button" data-reportar="${c.id}" data-tipo="comentario">Reportar</button></article>`).join('')||vacio('Sin comentarios todavía.')}</div><form id="comentario-form"><label class="campo">Tu comentario<textarea id="comentario-texto" maxlength="1000" required></textarea></label><button type="submit" class="capsula">Comentar</button></form>`);$('#comentario-form').onsubmit=async e=>{e.preventDefault();const texto=$('#comentario-texto').value;if(await accion({accion:'comentar',trabajoId:id,texto})){aviso('Comentario publicado.');await verTrabajo(id);}};}
async function reportar(tipo,id){await actualizarCliente();hoja('Reportar contenido',`<p>Antonio revisará el reporte.</p><form id="reporte-form"><label class="campo">Motivo<select id="reporte-motivo"><option value="sin_permiso">Foto sin permiso</option><option value="ofensivo">Contenido ofensivo</option><option value="incorrecto">Información incorrecta</option><option value="otro">Otro</option></select></label>${cliente?'':'<div id="captcha-social"></div>'}<p id="reporte-error" class="sub" role="status"></p><button type="submit" class="capsula">Enviar reporte</button></form>`);$('#reporte-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('/api/publico/reportar',{tipo,id,motivo:$('#reporte-motivo').value,captchaToken:tokenCaptcha},!!cliente);cerrar();aviso('Reporte recibido.');}catch(e){$('#reporte-error').textContent=e.message;}finally{b.disabled=false;}};if(!cliente)await captcha('reporte');}
async function misCitas(){const v=++version;if(!cliente){$('#contenido').innerHTML='<h1>Mis citas</h1>'+vacio('Entra con tu WhatsApp para ver tus citas en cualquier dispositivo.')+'<button type="button" class="capsula" data-entrar>Entrar con WhatsApp</button>';return;}$('#contenido').innerHTML='<h1>Mis citas</h1>'+vacio('Cargando tus citas…');try{const d=await api('/api/cliente/citas',undefined,true);if(v!==version)return;$('#contenido').innerHTML='<h1>Mis citas</h1><div class="grupo">'+(d.citas.map(c=>`<article class="resena"><h3>${esc(c.servicio)}</h3><p>${esc(c.negocio)} · ${esc(c.fecha)} · ${esc(c.hora)}</p><p class="sub">${esc(c.estado)} · ${money(c.precio)} · ${c.duracion} min</p>${c.slug?`<button type="button" data-perfil="${esc(c.slug)}">Ver salón</button>`:''}${c.puedeResenar?`<button type="button" class="capsula secundario" data-resenar="${esc(c.id)}" data-negocio="${c.negocioId}">Calificar mi cita</button>`:''}</article>`).join('')||vacio('Todavía no hay citas con tu WhatsApp.'))+'</div>';}catch(e){$('#contenido').innerHTML='<h1>Mis citas</h1>'+vacio(e.message);}}
function favoritos(){if(!cliente){$('#contenido').innerHTML='<h1>Favoritos</h1>'+vacio('Guarda salones y trabajos entrando con tu WhatsApp.')+'<button type="button" class="capsula" data-entrar>Entrar con WhatsApp</button>';return;}$('#contenido').innerHTML='<h1>Favoritos</h1><div class="tarjetas">'+perfiles.filter(p=>favorito('negocio',p.id)).map(local).join('')+'</div><div class="cuadricula">'+trabajos.filter(t=>favorito('trabajo',t.id)).map(t=>`<button type="button" data-trabajo="${t.id}">${foto(t.foto,t.servicio)}</button>`).join('')+'</div>'+(!cliente.guardados.length?vacio('Aún no guardaste salones ni trabajos.'):'');}
function miPerfil(){$('#contenido').innerHTML=`<h1>Perfil</h1>${cliente?`<div class="grupo"><div class="celda"><span class="l"><b>${esc(cliente.nombre)}</b><small>WhatsApp verificado</small></span></div><button type="button" class="celda" id="editar-nombre">Editar nombre público</button></div>`:`<p class="sub">Tus citas, favoritos y reseñas en un solo lugar.</p><button type="button" class="capsula" data-entrar>Entrar o registrarme con WhatsApp</button>`}<h2>Apariencia</h2><div class="segmentado">${[['light','White'],['dark','Dark']].map(([id,t])=>`<button type="button" data-tema="${id}" aria-selected="${document.documentElement.dataset.theme===id}">${t}</button>`).join('')}</div><div class="grupo"><a class="celda" href="/">Administrar mi negocio ↗</a><button type="button" class="celda" id="ubicacion-perfil">Ciudad o ubicación</button>${cliente?.moderador?'<button type="button" class="celda" id="moderacion">Reportes para revisar</button><button type="button" class="celda" id="verificar-negocios">Verificación de negocios</button>':''}${cliente?'<button type="button" class="celda" id="activar-avisos">Activar avisos en este dispositivo</button><button type="button" class="celda" id="quitar-avisos">Desactivar avisos</button><button type="button" class="celda" id="cerrar-sesion">Cerrar sesión</button>':''}</div>`;}
function ubicacion(){hoja('Tu ubicación',`<p class="sub">Se usa para calcular distancias. Tu ubicación exacta no se guarda.</p><button type="button" class="capsula" id="usar-ubicacion">Usar mi ubicación</button><form id="ciudad-form"><label class="campo">O elige ciudad o colonia<input id="ciudad" maxlength="150" autocomplete="address-level2" value="${esc(ciudad)}" placeholder="Monclova, Centro…"></label><button type="submit" class="capsula secundario">Buscar aquí</button></form>`);$('#ciudad-form').onsubmit=e=>{e.preventDefault();ciudad=$('#ciudad').value.trim();pos=null;try{localStorage.setItem('agendappx.cliente.ciudad',ciudad);}catch{}cerrar();perfil=null;tab='explorar';render();void cargar();};$('#usar-ubicacion').onclick=()=>{if(!navigator.geolocation)return aviso('Escribe tu ciudad o colonia.');try{localStorage.setItem('agendappx.ubicacion.preguntada','si');}catch{}navigator.geolocation.getCurrentPosition(p=>{pos={lat:p.coords.latitude,lon:p.coords.longitude};ciudad='';cerrar();perfil=null;tab='explorar';render();void cargar();},()=>aviso('Puedes continuar escribiendo tu ciudad o colonia.'),{enableHighAccuracy:false,timeout:10000,maximumAge:600000});};}
let demora;document.addEventListener('input',e=>{if(e.target.id==='buscar'){q=e.target.value;clearTimeout(demora);demora=setTimeout(()=>void cargar(),250);}});document.addEventListener('submit',e=>{if(e.target.id==='buscar-form'){e.preventDefault();void cargar();}});document.addEventListener('change',e=>{if(e.target.id==='orden'){orden=e.target.value;void cargar();}if(e.target.id==='perfil-servicio')void horasPerfil().catch(e=>aviso(e.message));});
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{
 if(b.dataset.tab){tab=b.dataset.tab;perfil=null;history.replaceState(null,'','/comunidad/');render();if(tab==='explorar')void cargar();if(tab==='favoritos'&&cliente){const d=await api('/api/cliente/favoritos',undefined,true);trabajos=d.trabajos;perfiles=d.negocios;favoritos();}}
 if(b.id==='buscar-circulo'){tab='explorar';perfil=null;render();$('#buscar').focus();}
 if(b.dataset.vista){vista=b.dataset.vista;render();void cargar();}if(b.dataset.categoria){q=b.dataset.categoria;render();void cargar();}if(b.dataset.filtro){if(b.dataset.filtro==='hoy')hoy=!hoy;else noche=!noche;b.setAttribute('aria-pressed',String(b.dataset.filtro==='hoy'?hoy:noche));void cargar();}
 if(b.dataset.perfil)await abrirPerfil(b.dataset.perfil);if(b.hasAttribute('data-volver')){perfil=null;tab='explorar';history.replaceState(null,'','/comunidad/');render();void cargar();}if(b.dataset.perfilTab){perfilTab=b.dataset.perfilTab;await dibujarPerfil();}
 if(b.dataset.agendar){cerrar();await reservar(b.dataset.agendar,b.dataset.servicio);}if(b.hasAttribute('data-perfil-reservar'))await reservar(perfil.slug,perfil.servicios[0]?.id);if(b.dataset.trabajo)await verTrabajo(b.dataset.trabajo);
 if(b.dataset.seguir){if(await accion({accion:'seguir',negocioId:b.dataset.seguir,activo:!cliente?.siguiendo?.includes(b.dataset.seguir)})){if(perfil)await dibujarPerfil();else render();}}
 if(b.dataset.gusta){if(await accion({accion:'me-gusta',trabajoId:b.dataset.gusta,activo:!cliente?.meGusta?.includes(b.dataset.gusta)}))void cargar();}
 if(b.dataset.guardar){if(await accion({accion:'guardar',tipo:'trabajo',destino:b.dataset.guardar,activo:!favorito('trabajo',b.dataset.guardar)}))render();}if(b.dataset.favorito){if(await accion({accion:'guardar',tipo:'negocio',destino:b.dataset.favorito,activo:!favorito('negocio',b.dataset.favorito)}))await dibujarPerfil();}
 if(b.dataset.compartir){const t=trabajos.find(t=>t.id===b.dataset.compartir),url=location.origin+'/'+t.slug+'#trabajo='+t.id;if(navigator.share)await navigator.share({title:t.negocio,text:t.servicio,url});else{await navigator.clipboard.writeText(url);aviso('Enlace copiado.');}}
 if(b.dataset.reportar)await reportar(b.dataset.tipo,b.dataset.reportar);if(b.hasAttribute('data-entrar'))await entrar();
 if(b.dataset.tema){document.documentElement.dataset.theme=b.dataset.tema;localStorage.setItem('agendappx.cliente.apariencia',b.dataset.tema);miPerfil();}
 if(['ubicacion','ubicacion-perfil'].includes(b.id))ubicacion();if(b.id==='activar-avisos')aviso(await window.AgendappxAvisos.activar('cliente'));if(b.id==='quitar-avisos')aviso(await window.AgendappxAvisos.desactivar('cliente'));if(b.id==='cerrar-sesion'){await window.AgendappxCuentas.salir();cliente=null;render();}
 if(b.id==='editar-nombre'){hoja('Nombre público',`<form id="nombre-form"><label class="campo">Nombre<input id="nombre-publico" maxlength="100" required value="${esc(cliente.nombre)}"></label><p class="sub">Este nombre aparecerá en tus comentarios y reseñas.</p><button type="submit" class="capsula">Guardar</button></form>`);$('#nombre-form').onsubmit=async e=>{e.preventDefault();if(await accion({accion:'perfil',nombre:$('#nombre-publico').value.trim()})){cerrar();miPerfil();}};}
 if(b.dataset.resenar){const negocioId=b.dataset.negocio,citaId=b.dataset.resenar;hoja('Calificar mi cita',`<form id="resena-form"><label class="campo">Calificación<select id="resena-estrellas">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} estrellas</option>`).join('')}</select></label><label class="campo">Tu experiencia<textarea id="resena-texto" maxlength="1500"></textarea></label><button class="capsula" type="submit">Publicar reseña verificada</button></form>`);$('#resena-form').onsubmit=async e=>{e.preventDefault();if(await accion({accion:'resena',negocioId,citaId,estrellas:+$('#resena-estrellas').value,texto:$('#resena-texto').value})){cerrar();void misCitas();}};}
 if(b.id==='verificar-negocios'){const d=await api('/api/publico/explorar',{q:'',ciudad:''});hoja('Verificar negocios','<p class="sub">Marca un salón solo después de comprobar que existe y confirmar su dirección y WhatsApp.</p><div class="grupo">'+d.negocios.map(n=>`<div class="celda"><span class="l">${esc(n.nombre)}<small>${esc(n.ciudad)} · ${esc(n.colonia)}</small></span><button type="button" data-verificar-negocio="${n.id}" data-verificado="${!n.verificado}">${n.verificado?'Quitar verificación':'Marcar verificado'}</button></div>`).join('')+'</div>');}if(b.dataset.verificarNegocio){await api('/api/cliente/verificar-negocio',{negocioId:b.dataset.verificarNegocio,verificado:b.dataset.verificado==='true'},true);b.textContent='Guardado';b.disabled=true;}if(b.id==='moderacion'){const d=await api('/api/cliente/reportes',undefined,true);hoja('Reportes',`<div class="grupo">${d.reportes.map(r=>`<article class="resena"><b>${esc(r.tipo)} · ${esc(r.motivo)}</b><p>${esc(r.texto)}</p><button type="button" data-resolver="${r.id}" data-retirar="true">Retirar contenido</button><button type="button" data-resolver="${r.id}" data-retirar="false">Conservar</button></article>`).join('')||vacio('No hay reportes pendientes.')}</div>`);}if(b.dataset.resolver){await api('/api/cliente/moderar',{id:b.dataset.resolver,retirar:b.dataset.retirar==='true'},true);b.closest('article').remove();aviso('Reporte revisado.');}
 if(b.id==='microfono'){const Voz=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Voz)return aviso('Usa el micrófono del teclado de tu iPhone para dictar la búsqueda.');const voz=new Voz();voz.lang='es-MX';voz.onresult=e=>{q=e.results[0][0].transcript;$('#buscar').value=q;void cargar();};voz.start();}
 }catch(err){if(err.name!=='AbortError')aviso(err.message||'No se pudo completar.');}});
document.addEventListener('agendappx:sesion',()=>void actualizarCliente());
await window.AgendappxCuentas.listo;await actualizarCliente();nav();render();await cargar();if(location.hash==='#mis-citas'){tab='citas';render();}const slug=location.pathname.match(/^\/([a-z0-9][a-z0-9-]{2,59})\/?$/)?.[1];if(slug&&!['comunidad','planes'].includes(slug))await abrirPerfil(slug);const compartido=location.hash.match(/^#trabajo=([a-f0-9-]{36})$/)?.[1];if(compartido){const d=await api('/api/publico/social',{q:'',ciudad:''});trabajos=d.trabajos;await verTrabajo(compartido);}
